random.seed(42)
t=5;a=3;cores=[set(range(i*a,(i+1)*a)) for i in range(t)];n=t*a
fam=[]
for i in range(t):
 outs=[(i+1)%t,(i+2)%t]
 for vals in itertools.product(*[cores[j] for j in outs]):
  fam.append((i,frozenset(cores[i]|set(vals))))
covers=[frozenset(c) for c in itertools.combinations(range(n),t-1)]
def tau_atleast_t(fam):return not any(all(C&F for i,F in fam) for C in covers)
def shift(fam,a,b):
 Fset=set(F for i,F in fam);out=[]
 for i,F in fam:
  G=(F-{b})|{a}
  if b in F and a not in F and G not in Fset:out.append((i,frozenset(G)))
  else:out.append((i,F))
 return out
assert tau_atleast_t(fam)
for trial in range(200):
 fs=list(fam);random.shuffle(fs)
 for e in list(fs):
  ns=[f for f in fs if f!=e]
  if tau_atleast_t(ns):fs=ns
 for core in cores:
  for aa,bb in itertools.permutations(core,2):
   ss=shift(fs,aa,bb)
   if not tau_atleast_t(ss):
    print('COUNTEREXAMPLE',trial,'edges',len(fs),'shift',aa,bb,flush=True)
